    if (!query.resolvedBillIds) {
        const bills = await Bill.find({ merchantTransId: { $regex: _.escapeRegExp(merchantTransId), $options: "i" } })
            .select({ _id: 1 })
            .limit(BILL_LOOKUP_LIMIT)
            .lean()
            .exec();
        if ((bills || []).length >= BILL_LOOKUP_LIMIT) {
            logger?.warn(
                `[PartnerCollectionTransExport] merchantTransId "${merchantTransId}" matches at least ` +
                `${BILL_LOOKUP_LIMIT} orders: only the first ${BILL_LOOKUP_LIMIT} are exported`
            );
        }
        query.resolvedBillIds = (bills || []).flatMap((b: any) => billIdVariants(b._id));
    }

